import{_ as a,o as r,c as i,a2 as n}from"./chunks/framework.CDpkVv68.js";const h=JSON.parse('{"title":"Aprender hechizos","description":"","frontmatter":{},"headers":[],"relativePath":"es/guide/magic/learning-spells.md","filePath":"es/guide/magic/learning-spells.md"}'),t={name:"es/guide/magic/learning-spells.md"};function o(s,e,l,d,c,p){return r(),i("div",null,[...e[0]||(e[0]=[n('<h1 id="learning-spells" tabindex="-1">Aprender hechizos <a class="header-anchor" href="#learning-spells" aria-label="Enlace permanente a &quot;Aprender hechizos&quot;">​</a></h1><p><strong>Estado:</strong> Propuesto · Disponibilidad no confirmada.</p><h2 id="tl-dr" tabindex="-1">TL;DR <a class="header-anchor" href="#tl-dr" aria-label="Enlace permanente a &quot;TL;DR&quot;">​</a></h2><ul><li>Un <a href="/Syrolands-Public/es/guide/glossary.html#core-pattern">Core Pattern</a> (estructura base del hechizo) es conocimiento aprendido, separado de Magery.</li><li>Los maestros, libros y la exploración pueden revelar nuevas posibilidades mágicas.</li><li>Un pergamino de lanzamiento normal no enseña su hechizo de forma permanente.</li></ul><p><span id="at-a-glance"></span></p><h2 id="how-it-works" tabindex="-1">Cómo funciona <a class="header-anchor" href="#how-it-works" aria-label="Enlace permanente a &quot;Cómo funciona&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Elemento</th><th>Qué significa para el jugador</th></tr></thead><tbody><tr><td>Descubrir</td><td>Busca maestros, academias, manuscritos, ruinas y otras fuentes de conocimiento.</td></tr><tr><td>Aprender</td><td>Adquiere un patrón independientemente de alcanzar un umbral de <a href="/Syrolands-Public/es/guide/characters/skills.html">habilidad</a>. Los requisitos exactos de enseñanza siguen abiertos.</td></tr><tr><td>Ejecutar</td><td>Magery apoya la fiabilidad; conocer un patrón difícil no garantiza lanzarlo con éxito.</td></tr><tr><td>Practicar y preparar</td><td>Desarrolla <a href="/Syrolands-Public/es/guide/characters/familiarity.html">Familiarity</a> (fluidez práctica) y elige patrones para <a href="/Syrolands-Public/es/guide/magic/memory-and-familiarity.html">Active Memory</a> (memoria activa).</td></tr></tbody></table><h2 id="compared-with-classic-uo" tabindex="-1">Comparado con UO clásico <a class="header-anchor" href="#compared-with-classic-uo" aria-label="Enlace permanente a &quot;Comparado con UO clásico&quot;">​</a></h2><table tabindex="0"><thead><tr><th>UO clásico</th><th>Orientación de Syrolands</th></tr></thead><tbody><tr><td>Los pergaminos de Magery pueden completar un libro de hechizos.</td><td>El aprendizaje permanente sigue fuentes de conocimiento y reglas de enseñanza; los pergaminos normales dan acceso temporal.</td></tr><tr><td>La habilidad influye en si el lanzamiento tiene éxito.</td><td>Se conserva la habilidad de ejecución, separando los logros de descubrimiento y práctica por patrón.</td></tr></tbody></table><p>Las reglas de UO varían según la época y el shard. <a href="https://uo.com/wiki/ultima-online-wiki/skills/an-introduction-to-spellcasting/" target="_blank" rel="noreferrer">UO oficial: lanzamiento de hechizos</a>.</p><h2 id="example" tabindex="-1">Ejemplo <a class="header-anchor" href="#example" aria-label="Enlace permanente a &quot;Ejemplo&quot;">​</a></h2><p>Un mago podría descubrir Remove Curse en un manuscrito y aun necesitar entrenamiento para lanzarlo con fiabilidad y preparación para no consultar esa referencia durante un peligro. El hechizo es un ejemplo ilustrativo.</p><h2 id="progression-trade-offs" tabindex="-1">Progresión y contrapartidas <a class="header-anchor" href="#progression-trade-offs" aria-label="Enlace permanente a &quot;Progresión y contrapartidas&quot;">​</a></h2><p>Las escuelas y el <a href="/Syrolands-Public/es/guide/glossary.html#mastery">Mastery</a> (dominio) más amplio siguen siendo distintos de los patrones individuales. La enseñanza entre jugadores y los objetos especiales de aprendizaje necesitan reglas; comprar un pergamino de lanzamiento no es un atajo automático al conocimiento permanente.</p><h2 id="related" tabindex="-1">Relacionado <a class="header-anchor" href="#related" aria-label="Enlace permanente a &quot;Relacionado&quot;">​</a></h2><p><a href="/Syrolands-Public/es/guide/magic/memory-and-familiarity.html">Memoria y Familiarity</a> · <a href="/Syrolands-Public/es/guide/magic/spellbooks-scrolls-and-reagents.html">Pergaminos y libros</a> · <a href="/Syrolands-Public/es/guide/characters/skills.html">Habilidades y maestros</a></p><h2 id="full-design-specification" tabindex="-1">Especificación de diseño completa <a class="header-anchor" href="#full-design-specification" aria-label="Enlace permanente a &quot;Especificación de diseño completa&quot;">​</a></h2><p>Consulta la especificación de diseño: <a href="/Syrolands-Public/es/game-design/magic/spell-knowledge.html">Aprender hechizos</a>.</p>',18)])])}const u=a(t,[["render",o]]);export{h as __pageData,u as default};
